import openpyxl
from openpyxl.utils import get_column_letter

def snap(path):
    wb = openpyxl.load_workbook(path)
    ws = wb['51998']
    out = {}
    for r in range(21, 27):
        for c in range(2, 9):
            cell = ws.cell(r,c)
            out[f'{get_column_letter(c)}{r}'] = (cell.style_id, cell.number_format)
    return out

a = snap('3_30468_answer_template_1092_input.xlsx')
b = snap('output.xlsx')
for k in sorted(a):
    if a[k] != b[k]:
        print('DIFF', k, a[k], b[k])
print('done, all equal:', a == b)
